'use strict';
const C=window.PMS, $=s=>document.querySelector(s), KEY='moa.personal-pms.v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 7a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z',check:'m7 12 3 3 7-7M5 3h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2Z',plus:'M12 5v14M5 12h14',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',search:'M21 21l-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z',database:'M20 5c0 2-4 3-8 3S4 7 4 5s4-3 8-3 8 1 8 3ZM4 5v14c0 2 4 3 8 3s8-1 8-3V5M4 12c0 2 4 3 8 3s8-1 8-3',sprout:'M12 22V12M12 15C4 15 2 10 3 5c7-1 10 3 9 10Zm0-3c0-6 4-9 9-8 0 6-3 9-9 8Z',clock:'M12 8v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',link:'m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m0 12a4 4 0 0 0 6 0l5-5a4 4 0 0 0-6-6l-1 1',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',flag:'M5 22V3m0 1c4-3 8 3 14 0v11c-6 3-10-3-14 0'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.calendar}"/></svg>`;
const statusNames={inbox:'수집함',todo:'할 일',doing:'진행 중',waiting:'대기',done:'완료',cancelled:'취소'};
const repeatNames={none:'반복 없음',daily:'매일',weekly:'매주',monthly:'매월',yearly:'매년'};
const priorityNames={high:'높음',normal:'보통',low:'낮음'};
const projectStatuses={active:'진행 중',paused:'보류',done:'완료'};
const weekdays=['일','월','화','수','목','금','토'];
let data=C.blank(),storageOK=true,toastTimer,view='calendar',now=new Date(),year=now.getFullYear(),month=now.getMonth(),selected=C.iso(now),query='',filterProject='',filterStatus='all',editing=null;
try{const raw=localStorage.getItem(KEY);if(raw)data=C.validate(JSON.parse(raw));}catch(e){storageOK=false;setTimeout(()=>toast('저장 데이터를 읽을 수 없습니다. 백업을 확인해주세요.',true),300);}
function today(){return C.iso(new Date());}
function uid(){return crypto.randomUUID?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').style.background=error?'#8b4654':'#2e3947';$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function save(next){try{C.validate(next);window.MoaDrive.save(next,data);data=next;storageOK=true;render();return true;}catch(e){toast('저장하지 못했습니다. '+(e.message||'저장 공간과 권한을 확인해주세요.'),true);return false;}}
function mutate(fn){const next=JSON.parse(JSON.stringify(data));fn(next);return save(next);}
function findProject(id){return data.projects.find(p=>p.id===id);}
function projectOptions(id=''){return `<option value="">개인 일정 · 프로젝트 없음</option>`+data.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===id?'selected':''}>${esc(p.title)}</option>`).join('');}
function options(obj,selected){return Object.entries(obj).map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('');}
function shortDate(s){const d=C.parse(s);return d?`${d.getFullYear()===new Date().getFullYear()?'':d.getFullYear()+'.'}${d.getMonth()+1}.${d.getDate()}`:'';}
function fullDate(s){const d=C.parse(s);return d?`${d.getFullYear()}년 ${d.getMonth()+1}월 ${d.getDate()}일`:'';}
function matches(x){return (!filterProject||x.projectId===filterProject)&&(!query||`${x.title} ${x.notes||''} ${findProject(x.projectId)?.title||''}`.toLowerCase().includes(query.toLowerCase()));}
function eventsOn(key){return data.events.filter(e=>C.occurs(e,key)&&matches(e)).sort((a,b)=>(a.time||'').localeCompare(b.time||''));}
function tasksOn(key){return data.tasks.filter(t=>t.due===key&&t.status!=='cancelled'&&matches(t));}
function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(n=>{n.innerHTML=icon(n.dataset.icon);});}
function render(){
 $('#projectCount').textContent=data.projects.filter(p=>p.status!=='done').length;$('#taskCount').textContent=data.tasks.filter(t=>!['done','cancelled'].includes(t.status)).length;
 $('#projectNav').innerHTML=data.projects.filter(p=>p.status!=='done').slice(0,7).map(p=>`<button class="project-nav" data-action="project-tasks" data-id="${esc(p.id)}"><span class="project-dot" style="background:${esc(p.color)}"></span><span>${esc(p.title)}</span></button>`).join('')||'<p class="empty-nav">새로운 프로젝트를 추가하고<br>할 일을 하나씩 모아보세요.</p>';
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
 const title={calendar:'나의 캘린더',year:'한 해를 한눈에',projects:'나의 프로젝트',tasks:'작은 일부터 하나씩'}[view];
 $('#pageTitle').innerHTML=title+'<span class="title-dot">.</span>';$('#crumb').textContent={calendar:'캘린더',year:'연간 보기',projects:'프로젝트',tasks:'할 일'}[view];
 $('#pageSubtitle').textContent={calendar:'하고 싶은 일과 해야 할 일, 한눈에 모아보세요.',year:'월을 눌러 상세 일정을 확인하세요. 연도는 자유롭게 바꿀 수 있어요.',projects:'목표부터 결과물까지, 나의 프로젝트를 이어가세요.',tasks:'아이디어를 모으고, 시작하고, 차근차근 마무리해요.'}[view];
 const action=view==='projects'?'new-project':view==='tasks'?'new-task':'new-event';$('#mainAdd').dataset.action=action;$('#mainAdd').innerHTML=icon('plus')+{projects:'프로젝트 추가',tasks:'할 일 추가',calendar:'일정 추가',year:'일정 추가'}[view];
 const currentToday=today();const active=data.tasks.filter(t=>!['done','cancelled'].includes(t.status));
 const stats=[['calendar','오늘 일정',data.events.filter(e=>C.occurs(e,currentToday)).length,'개'],['folder','진행 중 프로젝트',data.projects.filter(p=>p.status==='active').length,'개'],['clock','남은 할 일',active.length,'개'],['check','완료한 할 일',data.tasks.filter(t=>t.status==='done').length,'개']];
 $('#stats').innerHTML=stats.map(([i,label,count,unit])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><p class="stat-label">${label}</p><div class="stat-number">${count}<small>${unit}</small></div></div></div>`).join('');
 $('#saveStatus').innerHTML=`<span style="background:${storageOK?'#78a494':'#bc5c64'}"></span>${storageOK?esc(window.MoaDrive.info().status):'데이터 읽기 오류 · 백업 확인'}`;
 if(view==='calendar')renderCalendar();else if(view==='year')renderYear();else if(view==='projects')renderProjects();else renderTasks();fillIcons();
}
function yearControl(){return `<div class="date-control"><button class="icon-button" data-action="previous" aria-label="이전 ${view==='year'?'연도':'월'}" ${year===1&&(view==='year'||month===0)?'disabled':''}>${icon('left')}</button><input class="year-input" id="yearInput" type="number" min="1" max="9999" value="${year}" aria-label="연도"><span>년</span>${view==='calendar'?`<select class="month-select" id="monthInput" aria-label="월">${Array.from({length:12},(_,m)=>`<option value="${m}" ${m===month?'selected':''}>${m+1}월</option>`).join('')}</select>`:''}<button class="icon-button" data-action="next" aria-label="다음 ${view==='year'?'연도':'월'}" ${year===9999&&(view==='year'||month===11)?'disabled':''}>${icon('right')}</button></div>`;}
function searchBar(type){return `<div class="search-bar"><div class="search-wrap">${icon('search')}<input id="searchInput" type="search" placeholder="${type==='projects'?'프로젝트':'할 일'} 검색" aria-label="검색" value="${esc(query)}"></div>${type==='projects'?`<select id="statusFilter" class="filter" aria-label="프로젝트 상태"><option value="all">모든 상태</option>${options(projectStatuses,filterStatus)}</select>`:`<select id="projectFilter" class="filter" aria-label="프로젝트 필터"><option value="">모든 프로젝트</option>${data.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===filterProject?'selected':''}>${esc(p.title)}</option>`).join('')}</select>`}</div>`;}
function renderCalendar(){
 const grid=C.grid(year,month),td=today();
 $('#content').innerHTML=`<div class="calendar-layout"><div class="panel calendar-panel"><div class="calendar-toolbar">${yearControl()}<div class="calendar-switch"><button class="active" data-view="calendar">월간</button><button data-view="year">연간</button></div></div><div class="calendar-weekdays">${['월','화','수','목','금','토','일'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-grid" role="group" aria-label="${year}년 ${month+1}월 달력">${grid.map(d=>{
 const valid=!!C.parse(d.key);const ev=valid?eventsOn(d.key):[],ts=valid?tasksOn(d.key):[];const list=[...ev.map(e=>({title:e.title,time:e.time,type:'event'})),...ts.map(t=>({title:t.title,type:'task',done:t.status==='done'}))];
 return `<button class="day ${d.current?'':'outside'} ${d.key===td?'today':''} ${d.key===selected?'selected':''} ${d.weekday===0?'sunday':''}" data-action="select-day" data-date="${d.key}" aria-label="${esc(fullDate(d.key))}, 일정 ${ev.length}개, 할 일 ${ts.length}개" aria-pressed="${d.key===selected}" ${valid?'':'disabled'}><span class="day-label">${d.day}</span>${list.slice(0,3).map(e=>`<span class="calendar-chip ${e.type==='task'?'task-chip':''} ${e.done?'done':''}">${e.time?esc(e.time)+' ':''}${esc(e.title)}</span>`).join('')}${list.length>3?`<span class="more-count">+${list.length-3}개 더</span>`:''}</button>`;
 }).join('')}</div><div class="calendar-legend"><span><i class="legend-dot"></i>일정</span><span><i class="legend-dot green"></i>할 일 마감</span><span>날짜를 눌러 하루를 계획해보세요</span></div></div><aside><div class="panel day-panel" id="dayPanel"></div><div class="day-note"><strong>나만의 속도로 계획하기</strong>마감일과 작업 시간을 구분해보세요.<br>할 일에 기한을 적고, 달력에는<br>실제로 집중할 시간을 확보해요.</div></aside></div>`;renderDay();
}
function renderDay(){const d=C.parse(selected),ev=eventsOn(selected),ts=tasksOn(selected);const td=selected===today();
 $('#dayPanel').innerHTML=`<p class="section-eyebrow">${td?'TODAY':'MY DAILY PLAN'}</p><div class="day-panel-heading"><h2 class="day-title">${d.getMonth()+1}월 ${d.getDate()}일<span>${weekdays[d.getDay()]}요일</span></h2><button class="icon-button" data-action="new-event" data-date="${selected}" aria-label="선택한 날짜 일정 추가">${icon('plus')}</button></div><p class="day-summary">${ev.length}개의 일정 · ${ts.filter(t=>t.status!=='done').length}개의 할 일</p>${ev.map(e=>`<div class="agenda-item"><div class="agenda-time">${e.time?esc(e.time):'종일'}</div><div class="agenda-body"><button class="agenda-title" data-action="edit-event" data-id="${esc(e.id)}">${esc(e.title)}</button><div class="agenda-meta">${e.endTime?'~ '+esc(e.endTime)+' · ':''}${e.repeat!=='none'?repeatNames[e.repeat]+' 반복 · ':''}${esc(findProject(e.projectId)?.title||'개인 일정')}</div><div class="agenda-actions"><button class="text-button" data-action="duplicate-event" data-id="${esc(e.id)}">복제</button>${e.repeat!=='none'?`<button class="text-button" data-action="skip-event" data-id="${esc(e.id)}">이번만 제외</button>`:''}</div></div></div>`).join('')}${ts.map(t=>`<div class="agenda-item"><button class="icon-button" data-action="toggle-task" data-id="${esc(t.id)}" aria-label="${esc(t.title)} ${t.status==='done'?'완료 취소':'완료'}" aria-pressed="${t.status==='done'}">${t.status==='done'?icon('check'):'○'}</button><div class="agenda-body"><button class="agenda-title" style="${t.status==='done'?'text-decoration:line-through;opacity:.5':''}" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)}</button><div class="agenda-meta">마감 · ${esc(findProject(t.projectId)?.title||'개인 할 일')}</div>${t.url?`<div class="agenda-actions"><a class="text-button" href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">디자인 · 자료 열기 ↗</a></div>`:''}</div></div>`).join('')}${ev.length+ts.length===0?`<div class="empty-day"><div class="empty-illustration">${icon('calendar')}</div><strong>아직은 여유로운 하루예요</strong><p>작은 약속이나 집중할 시간을<br>하나씩 채워보세요.</p><button class="button full" data-action="new-event" data-date="${selected}">${icon('plus')}첫 일정 추가하기</button></div>`:`<button class="button full" style="margin-top:20px" data-action="new-event" data-date="${selected}">${icon('plus')}일정 추가하기</button>`}<button class="text-button full" style="margin-top:16px" data-action="new-task" data-date="${selected}">이 날짜에 마감할 일 추가</button>`;
}
function renderYear(){let html='';const td=today();for(let m=0;m<12;m++){const grid=C.grid(year,m);const count=grid.filter(d=>d.current).reduce((n,d)=>n+eventsOn(d.key).length,0);html+=`<button class="mini-month" data-action="open-month" data-month="${m}" aria-label="${year}년 ${m+1}월 열기"><div class="mini-month-header"><h3>${m+1}월</h3><span>일정 ${count}개</span></div><div class="mini-days">${['월','화','수','목','금','토','일'].map(d=>`<span class="mini-weekday">${d}</span>`).join('')}${grid.map(d=>`<span class="${d.current?'':'mini-outside'} ${td===d.key?'mini-today':''} ${d.current&&(eventsOn(d.key).length||tasksOn(d.key).length)?'has-event':''}">${d.day}</span>`).join('')}</div></button>`;}
 $('#content').innerHTML=`<div class="year-toolbar">${yearControl()}<p class="year-hint">과거의 기록부터 미래의 약속까지</p></div><div class="year-grid">${html}</div>`;
}
function renderProjects(){const list=data.projects.filter(p=>(filterStatus==='all'||p.status===filterStatus)&&(!query||`${p.title} ${p.notes}`.toLowerCase().includes(query.toLowerCase())));
 $('#content').innerHTML=searchBar('projects')+`<div class="project-grid">${list.map(p=>{const tasks=data.tasks.filter(t=>t.projectId===p.id&&t.status!=='cancelled'),done=tasks.filter(t=>t.status==='done').length,pct=tasks.length?Math.round(done/tasks.length*100):0;return `<article class="project-card"><div class="project-card-top"><div class="project-symbol" style="background:${esc(p.color)}19;color:${esc(p.color)}">${icon('folder')}</div><span class="badge ${p.status}">${projectStatuses[p.status]}</span><button class="icon-button" data-action="edit-project" data-id="${esc(p.id)}" aria-label="${esc(p.title)} 수정">···</button></div><h3>${esc(p.title)}</h3><p class="project-description">${esc(p.notes||'작은 할 일들을 모아 프로젝트를 완성해요.')}</p><div class="project-progress-meta"><span>할 일 ${done} / ${tasks.length} 완료</span><span>${pct}%</span></div><div class="progress-track"><span style="width:${pct}%;background:${esc(p.color)}"></span></div>${p.url?`<a class="text-button" style="margin-bottom:15px" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">미리캔버스 · 자료 폴더 열기 ↗</a>`:''}<div class="project-footer"><span>${p.deadline?shortDate(p.deadline)+' 마감':'기한 없이 차근차근'}</span><button class="text-button" data-action="project-tasks" data-id="${esc(p.id)}">할 일 보기 →</button></div></article>`;}).join('')}<button class="project-new" data-action="new-project">${icon('plus')}새 프로젝트 시작하기</button></div>${!list.length&&query?'<p class="task-help">검색 결과가 없습니다.</p>':''}`;
}
function renderTasks(){const tasks=data.tasks.filter(t=>matches(t));
 $('#content').innerHTML=searchBar('tasks')+`<div class="task-board">${['inbox','todo','doing','waiting','done'].map(status=>{const list=tasks.filter(t=>t.status===status);return `<section class="task-column"><div class="task-column-header"><span class="project-dot" style="background:${{inbox:'#a6b5cb',todo:'#a5b6d6',doing:'#a2bce1',waiting:'#d5bb99',done:'#9bbca9'}[status]}"></span>${statusNames[status]}<span class="count">${list.length}</span><button class="icon-button" data-action="new-task" data-status="${status}" aria-label="${statusNames[status]}에 할 일 추가">+</button></div>${list.map(t=>`<article class="task-card"><div class="task-project"><span class="project-dot" style="background:${esc(findProject(t.projectId)?.color||'#a3b3cb')}"></span>${esc(findProject(t.projectId)?.title||'개인 할 일')}</div><button class="agenda-title" data-action="edit-task" data-id="${esc(t.id)}"><h3>${esc(t.title)}</h3></button><div class="task-card-bottom"><span class="priority ${t.priority}">${priorityNames[t.priority]}</span><span class="task-due ${t.due&&t.due<today()&&t.status!=='done'?'overdue':''}">${t.due?esc(shortDate(t.due))+' 마감':'기한 없음'}</span></div>${t.url?`<a class="text-button" style="display:block;margin-top:13px" href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">디자인 · 자료 열기 ↗</a>`:''}<select class="task-quick-select" data-task-status="${esc(t.id)}" aria-label="${esc(t.title)} 상태 변경">${options(statusNames,t.status)}</select></article>`).join('')||'<div class="column-empty">할 일이 모이는 자리<br>+ 버튼으로 추가해보세요</div>'}</section>`;}).join('')}</div><p class="task-help">카드를 눌러 상세 내용을 수정하고, 카드 아래에서 상태를 바꿀 수 있어요. 연도가 바뀌어도 같은 프로젝트와 할 일이 이어집니다.</p>${tasks.some(t=>t.status==='cancelled')?`<details class="panel" style="padding:16px"><summary>취소한 할 일 ${tasks.filter(t=>t.status==='cancelled').length}개</summary>${tasks.filter(t=>t.status==='cancelled').map(t=>`<p><button class="text-button" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.title)} · 수정 / 복원</button></p>`).join('')}</details>`:''}`;
}
function field(label,name,type,value='',attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function selectField(label,name,content){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${content}</select></div>`;}
function editor(kind,id='',opts={}){let item=id?data[{event:'events',task:'tasks',project:'projects'}[kind]].find(x=>x.id===id):null;if(id&&!item)return;item=item||{};editing={kind,id,duplicate:!!opts.duplicate};
 const isDuplicate=!!opts.duplicate;const title=(isDuplicate?'복제한 ':id?'':'새로운 ')+{event:'일정',task:'할 일',project:'프로젝트'}[kind]+(id&&!isDuplicate?' 수정':' 추가');
 let body=field('이름','title','text',isDuplicate?item.title+' (복사)':item.title||'','required maxlength="200" placeholder="어떤 일을 계획하고 있나요?"');
 if(kind==='event'){body+=`<div class="field-row">${field('날짜','date','date',isDuplicate?selected:item.date||opts.date||selected,'required min="0001-01-01" max="9999-12-31"')}${selectField('프로젝트','projectId',projectOptions(item.projectId||filterProject))}</div><div class="field-row">${field('시작 시간 · 비우면 종일','time','time',item.time||'')}${field('종료 시간','endTime','time',item.endTime||'')}</div><div class="field-row">${selectField('반복','repeat',options(repeatNames,item.repeat||'none'))}${field('반복 종료일 · 선택','until','date',item.until||'','min="0001-01-01" max="9999-12-31"')}</div><p class="form-note">매월 31일·매년 2월 29일처럼 해당 날짜가 없는 경우는 건너뜁니다. ${item.repeat&&item.repeat!=='none'&&!isDuplicate?'수정하면 이 반복 일정 전체가 변경됩니다. 이번 회차만 제외하려면 하루 목록에서 ‘이번만 제외’를 누르세요.':''}</p>`;}
 if(kind==='task'){body+=`<div class="field-row">${selectField('프로젝트','projectId',projectOptions(item.projectId||filterProject))}${field('마감일 · 선택','due','date',item.due||opts.date||'','min="0001-01-01" max="9999-12-31"')}</div><div class="field-row">${selectField('상태','status',options(statusNames,item.status||opts.status||'todo'))}${selectField('우선순위','priority',options(priorityNames,item.priority||'normal'))}</div>${field('미리캔버스 · 자료 편집 링크','url','url',item.url||'','maxlength="2000" placeholder="https://www.miricanvas.com/…"')}`;}
 if(kind==='project'){body+=`<div class="field-row">${selectField('상태','status',options(projectStatuses,item.status||'active'))}${field('목표 마감일 · 선택','deadline','date',item.deadline||'','min="0001-01-01" max="9999-12-31"')}</div><div class="field-row">${field('프로젝트 색상','color','color',item.color||'#6992cb')}${field('미리캔버스 · 자료 폴더 링크','url','url',item.url||'','maxlength="2000" placeholder="https://…"')}</div>`;}
 body+=`<div class="field"><label for="f-notes">${kind==='project'?'목표 · 완료 조건 · 메모':'메모'}</label><textarea id="f-notes" name="notes" maxlength="4000" placeholder="필요한 내용이나 링크를 기록해두세요.">${esc(item.notes||'')}</textarea></div><div class="form-error" id="formError" role="alert"></div>`;
 $('#editor').innerHTML=`<form id="editForm"><div class="dialog-header"><h2 id="dialogTitle">${title}</h2><button class="icon-button" type="button" data-action="close-dialog" aria-label="닫기">${icon('close')}</button></div><div class="form-body">${body}</div><div class="dialog-footer">${id&&!isDuplicate?`<button type="button" class="button danger" data-action="delete-current">삭제</button>`:''}<div class="right"><button type="button" class="button" data-action="close-dialog">취소</button><button class="button primary" type="submit">${isDuplicate?'복제하여 저장':'저장하기'}</button></div></div></form>`;$('#editor').showModal();setTimeout(()=>$('#f-title').focus(),30);
}
function submitEditor(e){e.preventDefault();const f=new FormData(e.target),v=Object.fromEntries(f.entries()),kind=editing.kind,collection={event:'events',task:'tasks',project:'projects'}[kind],original=data[collection].find(x=>x.id===editing.id);v.title=v.title.trim();v.url=v.url?.trim()||'';
 if(!v.title){$('#formError').textContent='이름을 입력해주세요.';return;}
 if(v.url&&!/^https?:\/\//i.test(v.url)){$('#formError').textContent='링크는 https:// 또는 http://로 시작해야 합니다.';return;}
 if(kind==='event'){
 if(v.time&&v.endTime&&v.endTime<=v.time){$('#formError').textContent='종료 시간은 시작 시간 이후여야 합니다. 다음 날 일정은 별도로 추가해주세요.';return;}
 if(!v.time&&v.endTime){$('#formError').textContent='종료 시간을 쓰려면 시작 시간도 입력해주세요.';return;}
 if(v.repeat==='none')v.until='';if(v.until&&v.until<v.date){$('#formError').textContent='반복 종료일은 시작일 이후여야 합니다.';return;}
 v.exceptions=editing.duplicate?[]:(original?.exceptions||[]);delete v.url;
 }
 v.id=editing.id&&!editing.duplicate?editing.id:uid();
 if(kind==='task')v.completedAt=v.status==='done'?(original?.completedAt||today()):'';
 const next=JSON.parse(JSON.stringify(data));const idx=next[collection].findIndex(x=>x.id===v.id);if(idx<0)next[collection].push(v);else next[collection][idx]=v;
 try{C.validate(next);}catch(err){$('#formError').textContent=err.message;return;}
 if(save(next)){$('#editor').close();toast(editing.duplicate?'일정을 복제해 저장했어요.':'저장했어요.');}
}
function confirmAction(title,message,onYes,button='삭제하기'){const d=$('#confirmDialog');d.innerHTML=`<div class="dialog-header"><h2 id="confirmTitle">${esc(title)}</h2><button class="icon-button" data-action="close-confirm" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><p class="confirm-message">${esc(message)}</p></div><div class="dialog-footer"><div class="right"><button class="button" data-action="close-confirm">취소</button><button class="button ${button==='삭제하기'?'danger':'primary'}" id="confirmYes">${esc(button)}</button></div></div>`;$('#confirmYes').onclick=()=>{d.close();onYes();};d.showModal();}
function deleteCurrent(){const {kind,id}=editing;confirmAction('삭제할까요?',kind==='project'?'프로젝트를 삭제하면 연결된 할 일과 일정은 개인 항목으로 남습니다.':kind==='event'?'반복 일정은 전체 회차가 삭제됩니다. 이 작업은 되돌릴 수 없습니다.':'이 할 일을 삭제합니다. 이 작업은 되돌릴 수 없습니다.',()=>{
 const ok=mutate(d=>{const k={project:'projects',event:'events',task:'tasks'}[kind];d[k]=d[k].filter(x=>x.id!==id);if(kind==='project')for(const group of ['events','tasks'])d[group].forEach(x=>{if(x.projectId===id)x.projectId='';});});if(ok){if(filterProject===id)filterProject='';$('#editor').close();render();toast('삭제했어요.');}
 });}
function backup(){const d=$('#backupDialog');d.innerHTML=`<div class="dialog-header"><h2 id="backupTitle">백업 · 데이터 관리</h2><button class="icon-button" data-action="close-backup" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><p class="form-note">Drive 연결 전에는 이 브라우저에 저장됩니다. 연결 후에는 같은 Google 계정으로 연결한 기기끼리 동기화합니다. 연결 상태와 저장 대기를 확인하고, 별도 백업도 보관해주세요.</p><div class="backup-actions"><section class="backup-box"><h3>내 데이터 백업</h3><p>프로젝트 ${data.projects.length}개 · 할 일 ${data.tasks.length}개 · 일정 규칙 ${data.events.length}개를 JSON 파일로 저장합니다.</p><button class="button" data-action="export">${icon('download')}백업 내려받기</button></section><section class="backup-box"><h3>백업에서 복원</h3><p>이 앱에서 받은 JSON 백업을 선택하세요. 복원하면 현재 데이터 전체가 선택한 백업으로 교체됩니다.</p><button class="button" data-action="import">백업 파일 선택</button></section></div></div>`;d.showModal();}
function exportData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`캘린더-백업-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('백업을 내려받았어요.');}
function navigate(next){view=next;query='';filterProject='';filterStatus='all';document.body.classList.remove('menu-open');render();}
function applyYear(input){const value=Number(input.value);if(!Number.isInteger(value)||value<1||value>9999){input.value=year;toast('연도는 1부터 9999 사이로 입력해주세요.',true);return;}if(value===year)return;year=value;selected=C.iso(C.date(year,month,1));render();}
function moveDate(delta){if(view==='year'){year=Math.max(1,Math.min(9999,year+delta));}else{const n=C.date(year,month+delta);if(n.getFullYear()<1||n.getFullYear()>9999)return;year=n.getFullYear();month=n.getMonth();selected=C.iso(C.date(year,month,1));}render();}
document.addEventListener('click',e=>{
 const nav=e.target.closest('[data-view]');if(nav){navigate(nav.dataset.view);return;}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='new-event')editor('event','',{date:el.dataset.date});
 else if(a==='new-task')editor('task','',{date:el.dataset.date,status:el.dataset.status});
 else if(a==='new-project')editor('project');
 else if(a==='edit-event')editor('event',id);
 else if(a==='edit-task')editor('task',id);
 else if(a==='edit-project')editor('project',id);
 else if(a==='duplicate-event')editor('event',id,{duplicate:true});
 else if(a==='close-dialog')$('#editor').close();
 else if(a==='close-confirm')$('#confirmDialog').close();
 else if(a==='close-backup')$('#backupDialog').close();
 else if(a==='delete-current')deleteCurrent();
 else if(a==='select-day'){selected=el.dataset.date;const d=C.parse(selected);if(d.getMonth()!==month||d.getFullYear()!==year){year=d.getFullYear();month=d.getMonth();}render();}
 else if(a==='previous')moveDate(-1);
 else if(a==='next')moveDate(1);
 else if(a==='today'){const d=new Date();year=d.getFullYear();month=d.getMonth();selected=C.iso(d);navigate('calendar');}
 else if(a==='open-month'){month=Number(el.dataset.month);selected=C.iso(C.date(year,month,1));view='calendar';render();}
 else if(a==='project-tasks'){view='tasks';filterProject=id;query='';render();}
 else if(a==='toggle-task'){mutate(d=>{const t=d.tasks.find(x=>x.id===id);t.status=t.status==='done'?'todo':'done';t.completedAt=t.status==='done'?today():'';});}
 else if(a==='skip-event')confirmAction('이번 일정만 제외할까요?',`${fullDate(selected)} 회차만 제외합니다. 다른 반복 일정은 유지됩니다.`,()=>{if(mutate(d=>{const t=d.events.find(x=>x.id===id);t.exceptions=[...new Set([...t.exceptions,selected])];}))toast('이번 회차를 제외했어요.');},'이번만 제외');
 else if(a==='drive')openDrive();
 else if(a==='close-drive')$('#driveDialog').close();
 else if(a==='google-connect')window.MoaDrive.connect();
 else if(a==='google-sync')window.MoaDrive.sync();
 else if(a==='google-disconnect'){try{window.MoaDrive.disconnect();openDrive(false);}catch(err){toast(err.message,true);}}
 else if(a==='google-import')confirmAction('이 브라우저의 데이터를 Drive에 추가할까요?','연결 전 저장한 항목을 현재 Google 계정에 추가합니다. 같은 ID의 항목은 이 브라우저의 내용으로 바뀝니다.',()=>{try{window.MoaDrive.importLocal();openDrive(false);}catch(err){toast(err.message,true);}},'추가하기');
 else if(a==='backup')backup();
 else if(a==='export')exportData();
 else if(a==='import'){$('#importFile').value='';$('#importFile').click();}
});
document.addEventListener('change',e=>{
 if(e.target.id==='yearInput')applyYear(e.target);
 if(e.target.id==='monthInput'){month=Number(e.target.value);selected=C.iso(C.date(year,month,1));render();}
 if(e.target.id==='projectFilter'){filterProject=e.target.value;render();}
 if(e.target.id==='statusFilter'){filterStatus=e.target.value;render();}
 if(e.target.dataset.taskStatus){const id=e.target.dataset.taskStatus,status=e.target.value;mutate(d=>{const t=d.tasks.find(t=>t.id===id);t.status=status;t.completedAt=status==='done'?today():'';});}
});
document.addEventListener('keydown',e=>{if(e.target.id==='yearInput'&&e.key==='Enter'){e.preventDefault();applyYear(e.target);}});
document.addEventListener('focusout',e=>{if(e.target.id==='yearInput')applyYear(e.target);});
document.addEventListener('input',e=>{if(e.target.id==='searchInput'){query=e.target.value;const pos=e.target.selectionStart;view==='projects'?renderProjects():renderTasks();const input=$('#searchInput');input.focus();try{input.setSelectionRange(pos,pos);}catch(_){} }});
document.addEventListener('submit',e=>{if(e.target.id==='editForm')submitEditor(e);});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('백업 파일은 10MB 이하로 선택해주세요.',true);return;}try{const imported=C.validate(JSON.parse(await file.text()));confirmAction('백업으로 복원할까요?',`현재 데이터를 프로젝트 ${imported.projects.length}개, 할 일 ${imported.tasks.length}개, 일정 규칙 ${imported.events.length}개로 교체합니다. 필요한 현재 데이터는 먼저 백업해주세요.`,()=>{if(save(imported)){$('#backupDialog').close();filterProject='';render();toast('백업에서 복원했어요.');}},'복원하기');}catch(err){toast('백업을 읽을 수 없습니다. '+err.message,true);}});
window.addEventListener('storage',e=>{if(e.key===KEY&&!window.MoaDrive.info().account){try{data=e.newValue?C.validate(JSON.parse(e.newValue)):C.blank();render();toast('다른 탭의 변경을 반영했어요.');}catch(_){toast('다른 탭의 저장 데이터를 확인해주세요.',true);}}});
window.addEventListener('focus',()=>{if(today()!==C.iso(now)){now=new Date();render();}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();navigate('calendar');});
// Login gate: the app stays hidden until a Google account (OAuth test user) has signed in on this device.
function gate(){const locked=!window.MoaDrive.info().account;document.body.classList.toggle('locked',locked);if(locked)document.querySelectorAll('dialog[open]').forEach(d=>d.close());}
function gateStatus(message){const el=$('#gateStatus');if(el)el.textContent=message==='Google Drive 미연결'?'':message;}
data=window.MoaDrive.initial(data);
window.MoaDrive.init({replace(next){data=next;storageOK=true;gate();render();},status(message){gateStatus(message);const el=$('#saveStatus');if(el)el.innerHTML='<span></span>'+esc(message);const line=$('#driveState');if(line)line.textContent=message;const b=$('.drive-top');if(b)b.textContent=window.MoaDrive.info().account?'Drive 동기화':'Drive 연결';},open:openDrive,account(){gate();if($('#driveDialog').open)openDrive(false);}});
gate();fillIcons();render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
function openDrive(show=true){const info=window.MoaDrive.info(),d=$('#driveDialog');d.innerHTML=`<div class="dialog-header"><h2 id="driveTitle">Google Drive 동기화</h2><button class="icon-button" data-action="close-drive" aria-label="닫기">${icon('close')}</button></div><div class="form-body"><div class="drive-state" id="driveState" role="status">${esc(info.status)}</div><p class="form-note">${info.account?'연결 계정: '+esc(info.account)+'<br>':''}이 앱 전용 비공개 앱 데이터 공간에 저장합니다. 일반 Drive 파일 목록에는 표시되지 않습니다. 연결 전 데이터는 아래 버튼으로 추가할 수 있어요.</p><div class="drive-buttons"><button class="button primary" data-action="google-connect">${info.account?'Google 재연결 · 계정 선택':'Google 계정 연결'}</button><button class="button" data-action="google-sync" ${info.account?'':'disabled'}>지금 동기화</button></div>${info.account?`<p class="form-note">대기 중 변경 ${info.pending}건 · ${info.lastSync?'최근 확인 '+esc(info.lastSync):'아직 동기화 완료 전'}</p><div class="drive-buttons"><button class="button" data-action="google-import">이 브라우저의 기존 데이터 추가</button><button class="text-button" data-action="google-disconnect">연결 해제</button></div>`:''}<p class="form-note">접속 중 변경을 자동 저장하고 약 30초마다 다른 기기 변경을 확인합니다. 인터넷이 없거나 Google 인증이 만료되면 기기에 보관하며, 재연결하면 전송합니다. 같은 항목을 동시에 수정하면 정해진 순서에 따라 한 버전이 반영되고, 원본 변경 기록은 Drive에 남습니다.</p><details ${info.clientId?'':'open'}><summary>처음 한 번 · Google 연결 설정</summary><form id="driveConfigForm">${field('웹 애플리케이션 OAuth 클라이언트 ID','clientId','text',info.clientId,'required placeholder="…apps.googleusercontent.com"')}<p class="form-note">Google Cloud에서 Drive API와 OAuth 클라이언트를 설정하세요. 허용된 JavaScript 원본에 <code>${esc(location.origin)}</code>을 등록합니다. 클라이언트 보안 비밀번호는 입력하지 마세요.</p><button class="button" type="submit">연결 설정 저장</button><p id="driveConfigError" class="form-error" role="alert"></p></form></details><details><summary>아이폰 홈 화면에 설치</summary><p class="form-note">배포된 HTTPS 주소를 Safari로 열고 공유 → 홈 화면에 추가를 선택하세요. 현재 localhost 주소는 다른 기기에서 사용할 수 없습니다. 앱 화면을 저장해 오프라인에서도 열 수 있지만 Drive 동기화에는 인터넷과 Google 연결이 필요합니다.</p></details></div>`;if(show&&!d.open)d.showModal();}
document.addEventListener('submit',async e=>{if(e.target.id!=='driveConfigForm')return;e.preventDefault();const error=$('#driveConfigError');try{await window.MoaDrive.configure(new FormData(e.target).get('clientId').trim());openDrive(false);toast('설정했어요. Google 계정 연결을 눌러주세요.');}catch(err){error.textContent=err.message;}});
